<?php
require 'helpers.php'; requerirLogin();
if (!puede('gestionar_usuarios')) { http_response_code(403); exit('No tenés permiso para gestionar usuarios.'); }
$clienteId=(int)usuario()['cliente_id']; $error=''; $codigoNuevo=''; $ok='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 try { validarCsrf('csrf_usuarios'); $accion=(string)($_POST['accion']??'');
  if ($accion==='invitar') {
   $rol=(string)($_POST['rol']??''); $dias=filter_var($_POST['dias']??7,FILTER_VALIDATE_INT);
   if (!in_array($rol,['encargado','operador'],true) || $dias===false || $dias<1 || $dias>30) throw new RuntimeException('Seleccioná un perfil y una vigencia de entre 1 y 30 días.');
   $q=db()->prepare('SELECT id FROM costobene_roles WHERE nombre=?');$q->execute([$rol]);$rolId=(int)$q->fetchColumn(); if(!$rolId) throw new RuntimeException('El rol solicitado no está configurado.');
   $codigo=strtoupper(bin2hex(random_bytes(5))); $ins=db()->prepare('INSERT INTO costobene_invitaciones (cliente_id,rol_id,rol,codigo_hash,creado_por,vence_en) VALUES (?,?,?,?,?,DATE_ADD(NOW(),INTERVAL ? DAY))');
   $ins->execute([$clienteId,$rolId,$rol,hash('sha256',$codigo),(int)usuario()['id'],$dias]); $codigoNuevo=$codigo;
  } elseif ($accion==='estado_usuario') { $id=(int)($_POST['id']??0);$activo=(int)($_POST['activo']??0);if($id===(int)usuario()['id'])throw new RuntimeException('No podés desactivar tu propia cuenta.');$q=db()->prepare('UPDATE costobene_usuarios SET activo=? WHERE id=? AND cliente_id=?');$q->execute([$activo?1:0,$id,$clienteId]);$ok='Estado del usuario actualizado.'; } elseif ($accion==='revocar') { $id=(int)($_POST['id']??0); $q=db()->prepare('UPDATE costobene_invitaciones SET revocada=1 WHERE id=? AND cliente_id=? AND usada_en IS NULL');$q->execute([$id,$clienteId]);$ok='Invitación revocada.'; }
 } catch(Throwable $e) { $error=$e instanceof RuntimeException?$e->getMessage():'No se pudo procesar la invitación.'; }
}
$st=db()->prepare('SELECT u.id,u.nombre,u.apellido,u.correo,u.activo,GROUP_CONCAT(r.nombre SEPARATOR ", ") roles FROM costobene_usuarios u JOIN costobene_usuarios_roles ur ON ur.usuario_id=u.id JOIN costobene_roles r ON r.id=ur.rol_id WHERE u.cliente_id=? GROUP BY u.id ORDER BY u.id');$st->execute([$clienteId]);$usuarios=$st->fetchAll();
$st=db()->prepare('SELECT i.id,i.rol,i.vence_en,i.usada_en,i.revocada FROM costobene_invitaciones i WHERE i.cliente_id=? ORDER BY i.id DESC LIMIT 30');$st->execute([$clienteId]);$invitaciones=$st->fetchAll();$csrf=csrfToken('csrf_usuarios');$paginaActual='usuarios';
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Usuarios - CostoPyme</title><link rel="stylesheet" href="style.css"></head><body><div class="app-shell"><?php require 'menu.php';?><main class="main"><header class="page-head"><div><h1>Usuarios e invitaciones</h1><p>Administrá quién puede acceder a la información de tu empresa.</p></div></header>
<?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><?php if($ok):?><div class="success"><?=h($ok)?></div><?php endif;?>
<?php if($codigoNuevo):?><section class="panel"><h2>Invitación creada</h2><p>Compartí este código con la persona invitada. Se muestra una sola vez.</p><div class="invite-code"><?=h($codigoNuevo)?></div><button type="button" onclick="navigator.clipboard.writeText('<?=h($codigoNuevo)?>')">Copiar código</button><p class="help">La invitación está vinculada a tu empresa y al perfil seleccionado.</p></section><?php endif;?>
<section class="panel"><h2>Crear invitación</h2><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="accion" value="invitar"><div class="form-grid"><label>Perfil<select name="rol"><option value="encargado">Encargado</option><option value="operador">Operador</option></select></label><label>Vigencia (días)<input type="number" name="dias" min="1" max="30" value="7" required></label></div><div class="actions"><button>＋ Generar invitación</button></div></form></section>
<section class="panel"><h2>Usuarios de la empresa</h2><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Perfil</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($usuarios as $u):?><tr><td><?=h($u['nombre'].' '.$u['apellido'])?></td><td><?=h($u['correo'])?></td><td><?=h($u['roles'])?></td><td><?=$u['activo']?'Activo':'Inactivo'?></td><td><?php if((int)$u['id']!==(int)usuario()['id']):?><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="accion" value="estado_usuario"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><input type="hidden" name="activo" value="<?=$u['activo']?0:1?>"><button class="btn-secondary"><?=$u['activo']?'Desactivar':'Activar'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>Invitaciones recientes</h2><div class="table-wrap"><table><thead><tr><th>Perfil</th><th>Vence</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($invitaciones as $i):?><tr><td><?=h($i['rol'])?></td><td><?=h($i['vence_en'])?></td><td><?=$i['usada_en']?'Utilizada':($i['revocada']?'Revocada':(strtotime($i['vence_en'])<time()?'Vencida':'Pendiente'))?></td><td><?php if(!$i['usada_en']&&!$i['revocada']&&strtotime($i['vence_en'])>=time()):?><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="accion" value="revocar"><input type="hidden" name="id" value="<?=(int)$i['id']?>"><button class="btn-secondary">Revocar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
</main></div></body></html>
